import { BUILDING_BLOCK_BASE_PREMIUM, BUILDING_BLOCK_SIZE, basePremiumOf } from "./price-list.js";

export interface Scenario {
  customer: { yearsWithMHPCO: number };
  steps: QuoteStep[];
}

export interface QuoteStep {
  op: "quote";
  items: Item[];
}

export interface Item {
  type: string;
}

export interface QuoteResult {
  premium: number;
}

export interface ScenarioResults {
  results: QuoteResult[];
}

const FIRST_INSURANCE_SURCHARGE_PERCENT = 10;
const PROCESSING_FEE = 5;
const PERCENT = 100;

export function processScenario(scenario: Scenario): ScenarioResults {
  const [step] = scenario.steps;
  return { results: [{ premium: quotePremium(step.items) }] };
}

function quotePremium(items: Item[]): number {
  const basePremium = policyBasePremium(items);
  const firstInsuranceSurcharge = (basePremium * FIRST_INSURANCE_SURCHARGE_PERCENT) / PERCENT;
  return roundPremiumInFavorOfMHPCO(basePremium + firstInsuranceSurcharge + PROCESSING_FEE);
}

