import { describe, expect, it } from "vitest";
import { processScenario, type QuoteStep, type Scenario } from "./claim-office.js";
import type { Item } from "./item.js";

const NEWCOMER = { yearsWithMHPCO: 0 };

function quote(...items: Item[]): QuoteStep {
  return { op: "quote", items };
}

function copies(count: number, item: Item): Item[] {
  return Array.from({ length: count }, () => ({ ...item }));
}

const runes = (count: number) => copies(count, { type: "rune" });
const moonstones = (count: number) => copies(count, { type: "moonstone" });

function resultsOf(steps: Scenario["steps"], customer = NEWCOMER) {
  return processScenario({ customer, steps }).results;
}

describe("MHPCO claim office scenario", () => {
  describe("quote: base premium, first insurance surcharge and processing fee", () => {
    it("empty item list -> premium 5 (only the processing fee)", () => {
      expect(resultsOf([quote()])).toEqual([{ premium: 5 }]);
    });
    it("sword -> premium 115 (100 base + 10 first insurance + 5 fee)", () => {
      expect(resultsOf([quote({ type: "sword" })])).toEqual([{ premium: 115 }]);
    });
    it("amulet -> premium 71 (60 base + 6 first insurance + 5 fee)", () => {
      expect(resultsOf([quote({ type: "amulet" })])).toEqual([{ premium: 71 }]);
    });
    it("staff -> premium 93 (80 base + 8 first insurance + 5 fee)", () => {
      expect(resultsOf([quote({ type: "staff" })])).toEqual([{ premium: 93 }]);
    });
    it("potion -> premium 49 (40 base + 4 first insurance + 5 fee)", () => {
      expect(resultsOf([quote({ type: "potion" })])).toEqual([{ premium: 49 }]);
    });
    it("sword and amulet -> policy base premium 160 -> premium 181 (160 + 16 first insurance + 5 fee)", () => {
      expect(resultsOf([quote({ type: "sword" }, { type: "amulet" })])).toEqual([{ premium: 181 }]);
    });
  });

  describe("quote: components and building blocks", () => {
    it("2 runes -> 50 base premium -> premium 60 (50 + 5 first insurance + 5 fee)", () => {
      expect(resultsOf([quote(...runes(2))])).toEqual([{ premium: 60 }]);
    });
    it("2 moonstones -> 50 base premium -> premium 60 (50 + 5 first insurance + 5 fee)", () => {
      expect(resultsOf([quote(...moonstones(2))])).toEqual([{ premium: 60 }]);
    });
    it("1 rune -> 25 + 2.5 + 5 = 32.5 -> premium 33 (rounded up in the MHPCO's favor)", () => {
      expect(resultsOf([quote(...runes(1))])).toEqual([{ premium: 33 }]);
    });
    it("3 runes -> 60 base premium (block applies) -> premium 71 (60 + 6 + 5)", () => {
      expect(resultsOf([quote(...runes(3))])).toEqual([{ premium: 71 }]);
    });
    it("4 runes -> 100 base premium (no block: block requires exactly 3) -> premium 115 (100 + 10 + 5)", () => {
      expect(resultsOf([quote(...runes(4))])).toEqual([{ premium: 115 }]);
    });
    it("7 runes -> 175 base premium -> calculation yields 197.5 -> premium 198 (rounded up)", () => {
      expect(resultsOf([quote(...runes(7))])).toEqual([{ premium: 198 }]);
    });
    it("2 runes + 1 moonstone -> 75 base premium (no block: different types) -> premium 88 (75 + 7.5 + 5 = 87.5 rounded up)", () => {
      expect(resultsOf([quote(...runes(2), ...moonstones(1))])).toEqual([{ premium: 88 }]);
    });
    it("3 runes + 3 moonstones -> 120 base premium (two separate blocks) -> premium 137 (120 + 12 + 5)", () => {
      expect(resultsOf([quote(...runes(3), ...moonstones(3))])).toEqual([{ premium: 137 }]);
    });
    it("3 swords -> 300 base premium (the block is offered for components only) -> premium 335 (300 + 30 + 5)", () => {
      expect(resultsOf([quote(...copies(3, { type: "sword" }))])).toEqual([{ premium: 335 }]);
    });
  });

  describe("quote: premium modifiers", () => {
    it("newcomer with a cursed sword (steel, enchantment 3) -> premium 165 (100 base + 50 curse + 10 first insurance + 5 fee)", () => {
      const cursedSword = { type: "sword", material: "steel", enchantment: 3, cursed: true };

      expect(resultsOf([quote(cursedSword)], NEWCOMER)).toEqual([{ premium: 165 }]);
    });
    it("cursed sword + plain amulet -> curse adds 50 (50 % of the sword's base premium only): 210 before further modifiers -> premium 231 (+ 16 first insurance + 5 fee)", () => {
      const items = [{ type: "sword", cursed: true }, { type: "amulet" }];

      expect(resultsOf([quote(...items)])).toEqual([{ premium: 231 }]);
    });
    it("sword with exactly enchantment 5 -> high-enchantment surcharge applies -> premium 145 (100 + 30 + 10 + 5)", () => {
      expect(resultsOf([quote({ type: "sword", enchantment: 5 })])).toEqual([{ premium: 145 }]);
    });
    it.todo("sword with enchantment 4 -> no high-enchantment surcharge -> premium 115");
    it.todo("plain sword + amulet with enchantment 5 -> surcharge adds 18 (30 % of the amulet's base premium only) -> premium 199 (160 + 18 + 16 + 5)");
    it.todo("cursed sword with exactly enchantment 5 -> both surcharges apply -> premium 195 (100 + 50 + 30 + 10 + 5)");
    it.todo("cursed sword with enchantment 4 -> only the curse surcharge applies -> premium 165");
    it.todo("customer with exactly 2 years with MHPCO -> loyalty discount applies -> sword premium 95 (100 - 20 loyalty + 10 + 5)");
    it.todo("customer with 1 year with MHPCO -> no loyalty discount -> sword premium 115");
    it.todo("loyalty discount applies to the policy base premium, not to surcharges: 2 years, cursed sword + amulet -> premium 199 (160 + 50 - 32 + 16 + 5)");
    it.todo("second quote in the scenario -> 15 % follow-up contract discount -> sword premium 100 (100 + 10 - 15 + 5); the first quote stays 115");
    it.todo("third quote in the scenario -> follow-up discount applies to each contract after the first -> sword premium 100");
    it.todo("long-standing customer's second contract: 3 years, cursed sword (steel, enchantment 7) -> premium 160 (100 + 50 + 30 - 20 + 10 - 15 = 155 + 5 fee)");
    it.todo("intermediate amounts are kept as fractions: loyal customer's second contract for 1 rune -> 25 - 5 + 2.5 - 3.75 + 5 = 23.75 -> premium 24");
  });

  describe("claim: standard reimbursement, deductible and cap", () => {
    it.todo("regular sword (steel, enchantment 3), damage 500 -> payout 400 (minus 100 deductible), remainingCap 1600 (cap 2000 = 2 x 1000)");
    it.todo("amulet, damage 200 -> payout 100, remainingCap 1100 (cap 1200 = 2 x 600)");
    it.todo("staff, damage 200 -> payout 100, remainingCap 1500 (cap 1600 = 2 x 800)");
    it.todo("potion, damage 200 -> payout 100, remainingCap 700 (cap 800 = 2 x 400)");
    it.todo("rune (insurance value 250), damage 200 -> payout 100, remainingCap 400 (cap 500)");
    it.todo("moonstone (insurance value 250), damage 200 -> payout 100, remainingCap 400 (cap 500)");
    it.todo("damage 60 below the deductible -> payout 0, remainingCap 2000 (chosen reading: the deductible never makes a payout negative)");
  });

  describe("claim: enchantment threshold vs. dragon material", () => {
    it.todo("steel sword, enchantment 9, damage 1000 -> payout 400 (50 % first, then deductible: 500 - 100)");
    it.todo("dragon-material sword with exactly enchantment 8, damage 1000 -> payout 400 (high-enchantment clause applies, then deductible)");
    it.todo("steel sword, enchantment 7, damage 1000 -> payout 900 (below the enchantment >= 8 threshold: full reimbursement minus deductible)");
    it.todo("dragon-material sword, enchantment 9, damage 1000 -> payout 400 (both clauses apply; the 50 % rule wins)");
    it.todo("dragon-material sword, enchantment 5, damage 800 -> payout 700 (full reimbursement, then deductible)");
    it.todo("payout calculation that yields 350.5 (enchantment 9 sword, damage 901) -> payout 350 (rounded down), remainingCap 1650");
  });

  describe("claim: several damages and insurance sum", () => {
    it.todo("dragon attack damages sword (500) and amulet (300) -> payout 600 (deductible once per damaged item), remainingCap 2600 (insurance sum 1600, cap 3200)");
    it.todo("policy covers two swords, both damaged (500 and 300) -> each damage entry has its own deductible: payout 600, remainingCap 3400 (insurance sum 2000, cap 4000)");
    it.todo("intermediate payouts are kept as fractions: two enchantment-9 swords, each damage 901 -> 350.5 + 350.5 -> payout 701");
    it.todo("cursed sword -> cap 2000 (premium modifiers do not raise the cap): damage 500 -> payout 400, remainingCap 1600");
    it.todo("sword and 3 runes (a block) -> insurance sum 1750, cap 3500 (block discount does not affect the insurance sum): sword damage 500 -> payout 400, remainingCap 3100");
  });

  describe("claim: cap exhaustion across steps", () => {
    it.todo("sword, two successive claims of 1500 -> first: payout 1400, remainingCap 600; second: payout 600, remainingCap 0 (reduced to the remaining cap)");
    it.todo("the cap is tracked per policy, referenced by the quote's step index: sword (step 0) and amulet (step 1) policies keep separate caps");
    it.todo("schema example (5 years, silver amulet, fire damage 200) -> results in step order: [{premium: 59}, {payout: 100, remainingCap: 1100}]");
  });
});

