export interface Customer {
  yearsWithMHPCO: number;
}

export function quotePremium(items: Item[], customer: Customer): number {
  const basePremium = policyBasePremium(items);
  const loyaltyDiscount =
    customer.yearsWithMHPCO >= LOYALTY_YEARS ? percentOf(basePremium, LOYALTY_DISCOUNT_PERCENT) : 0;
  const firstInsuranceSurcharge = percentOf(basePremium, FIRST_INSURANCE_SURCHARGE_PERCENT);
  return roundPremiumInFavorOfMHPCO(
    basePremium + riskSurcharges(items) - loyaltyDiscount + firstInsuranceSurcharge + PROCESSING_FEE,
  );
}

function riskSurcharges(items: Item[]): number {
  return items.reduce((sum, item) => sum + percentOf(basePremiumOf(item.type), riskSurchargePercent(item)), 0);
}

function riskSurchargePercent(item: Item): number {
  const curseSurcharge = item.cursed ? CURSE_SURCHARGE_PERCENT : 0;
  const highEnchantmentSurcharge = isHighlyEnchanted(item) ? HIGH_ENCHANTMENT_SURCHARGE_PERCENT : 0;
  return curseSurcharge + highEnchantmentSurcharge;
}

function isHighlyEnchanted(item: Item): boolean {
  return (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_LEVEL;
}

function percentOf(amount: number, percent: number): number {
  return (amount * percent) / PERCENT;
}

function roundPremiumInFavorOfMHPCO(premium: number): number {
  return Math.ceil(premium);
}

