import type { Item } from "./item.js";
import { quotePremium, type Customer } from "./premium.js";

export interface Scenario {
  customer: Customer;
  steps: QuoteStep[];
}

export interface QuoteStep {
  op: "quote";
  items: Item[];
}

export interface QuoteResult {
  premium: number;
}

export interface ScenarioResults {
  results: QuoteResult[];
}

export function processScenario(scenario: Scenario): ScenarioResults {
  const [step] = scenario.steps;
  return { results: [{ premium: quotePremium(step.items, scenario.customer) }] };
}

