export interface Scenario {
  customer: { yearsWithMHPCO: number };
  steps: Step[];
}

export type Step = QuoteStep | ClaimStep;

export interface QuoteStep {
  op: "quote";
  items: Item[];
}

export interface ClaimStep {
  op: "claim";
  policy: number;
  incident: { cause: string; damages: Damage[] };
}

export interface Damage {
  itemType: string;
  amount: number;
}

export interface QuoteResult {
  premium: number;
}

export interface ClaimResult {
  payout: number;
  remainingCap: number;
}

export interface ScenarioResults {
  results: (QuoteResult | ClaimResult)[];
}

export function processScenario(scenario: Scenario): ScenarioResults {
  const results = scenario.steps.map((step, previousContracts) =>
    step.op === "quote"
      ? { premium: quotePremium(step.items, { ...scenario.customer, previousContracts }) }
      : settleClaim(step.incident.damages),
  );
  return { results };
}

function settleClaim(damages: Damage[]): ClaimResult {
  const payout = damages[0].amount - 100;
  return { payout, remainingCap: 2000 - payout };
}

