import type { Item } from "./item.js";
import { insuranceSum } from "./price-list.js";

const DEDUCTIBLE = 100;
const CAP_PER_INSURANCE_SUM = 2;

export interface Damage {
  itemType: string;
  amount: number;
}

export interface ClaimSettlement {
  payout: number;
  remainingCap: number;
}

export function settleClaim(insuredItems: Item[], damages: Damage[]): ClaimSettlement {
  const payout = damages[0].amount - DEDUCTIBLE;
  return { payout, remainingCap: CAP_PER_INSURANCE_SUM * insuranceSum(insuredItems) - payout };
}

