import type { Item } from "./item.js";
import { percentOf } from "./percent.js";
import { insuranceSum } from "./price-list.js";
import { roundPayoutInFavorOfMHPCO } from "./rounding.js";

const REDUCED_REIMBURSEMENT_ENCHANTMENT_LEVEL = 8;
const REDUCED_REIMBURSEMENT_PERCENT = 50;
const DEDUCTIBLE = 100;
const CAP_PER_INSURANCE_SUM = 2;

export interface Policy {
  insuredItems: Item[];
  remainingCap: number;
}

export interface Damage {
  itemType: string;
  amount: number;
}

export interface ClaimSettlement {
  payout: number;
  remainingCap: number;
}

export function issuePolicy(insuredItems: Item[]): Policy {
  return { insuredItems, remainingCap: CAP_PER_INSURANCE_SUM * insuranceSum(insuredItems) };
}

export function settleClaim(policy: Policy, damages: Damage[]): ClaimSettlement {
  const damagePayouts = damages.reduce((sum, damage) => sum + damagePayout(policy.insuredItems, damage), 0);
  const payout = Math.min(roundPayoutInFavorOfMHPCO(damagePayouts), policy.remainingCap);
  policy.remainingCap -= payout;
  return { payout, remainingCap: policy.remainingCap };
}

function damagePayout(insuredItems: Item[], damage: Damage): number {
  const damagedItem = insuredItems.find((item) => item.type === damage.itemType);
  return afterDeductible(reimbursementOf(damagedItem, damage.amount));
}

// Dragon material is "fully reimbursed", which is also the standard reimbursement, and the
// enchantment clause wins when both apply — so the material needs no rule of its own here.
function reimbursementOf(damagedItem: Item | undefined, damageAmount: number): number {
  const isReducedByEnchantment = (damagedItem?.enchantment ?? 0) >= REDUCED_REIMBURSEMENT_ENCHANTMENT_LEVEL;
  return isReducedByEnchantment ? percentOf(damageAmount, REDUCED_REIMBURSEMENT_PERCENT) : damageAmount;
}

function afterDeductible(reimbursement: number): number {
  return Math.max(0, reimbursement - DEDUCTIBLE);
}

