import { describe, it } from "vitest";

describe("claim-office CLI", () => {
  describe("stdin/stdout contract", () => {
    it.todo("valid scenario JSON on stdin -> exit status 0, results JSON on stdout, nothing on stderr");
  });

  // Chosen reading for all rejections: the whole scenario fails, so no results are written to stdout.
  describe("rejections: non-zero exit status, error description on stderr, no results on stdout", () => {
    it.todo("quote includes an item with an unknown type (broomstick) -> non-zero exit, error on stderr, no results on stdout");
    it.todo("claim damages an item that is not part of the policy (amulet damaged, only a sword insured) -> non-zero exit, error on stderr");
    it.todo("claim damages an item with an unknown type (broomstick) -> non-zero exit, error on stderr");
    it.todo("claim contains a damage entry with amount -200 -> non-zero exit, error on stderr");
    it.todo("claim has more damage entries of a type than the policy covers (two sword damages, one sword insured) -> non-zero exit, whole claim rejected");
    it.todo("claim refers to a step that created no policy -> non-zero exit, error on stderr (chosen reading: an invalid policy reference is rejected like other invalid claims)");
  });

  describe("claim-office executable", () => {
    it.todo("schema example piped through the executable -> exit status 0, stdout {\"results\":[{\"premium\":59},{\"payout\":100,\"remainingCap\":1100}]}, empty stderr");
    it.todo("unknown item type piped through the executable -> non-zero exit status, error description on stderr, empty stdout");
  });
});

