import { Policy, type ClaimSettlement, type Damage } from "./policy.js";
import type { Item } from "./item.js";
import { quotePremium } from "./premium.js";

export interface Scenario {
  customer: { yearsWithMHPCO: number };
  steps: Step[];
}

export type Step = QuoteStep | ClaimStep;

export interface QuoteStep {
  op: "quote";
  items: Item[];
}

export interface ClaimStep {
  op: "claim";
  policy: number;
  incident: { cause: string; damages: Damage[] };
}

export interface QuoteResult {
  premium: number;
}

export interface ScenarioResults {
  results: (QuoteResult | ClaimSettlement)[];
}

export function processScenario(scenario: Scenario): ScenarioResults {
  const policies = new Map<number, Policy>();
  const results = scenario.steps.map((step, stepIndex) => {
    if (step.op === "quote") {
      const customer = { ...scenario.customer, previousContracts: policies.size };
      policies.set(stepIndex, new Policy(step.items));
      return { premium: quotePremium(step.items, customer) };
    }
    return policies.get(step.policy)!.settleClaim(step.incident.damages);
  });
  return { results };
}

